import java.util.*;

public class Main {
    public static void main(String[] args) {
        long target = new Scanner(System.in).nextLong();
        int bestValue = -1, bestPresses = 0;
        long bestDiff = 0;
        for (int value = 0; value < 10000; value++) {
            String d = Integer.toString(value);
            int presses = d.length();
            for (int i = 1; i < d.length(); i++)
                if (d.charAt(i) != d.charAt(i - 1)) presses += 2; // finger move between different keys
            // Up to two digits are seconds; otherwise the last two digits are seconds (may reach 99).
            long seconds = d.length() <= 2 ? value : (value / 100) * 60L + value % 100;
            long diff = Math.abs(seconds - target);
            if (diff * 10 > target) continue;
            // Values are scanned in increasing order, so a strict comparison keeps the smallest value on ties.
            if (bestValue < 0 || presses < bestPresses || (presses == bestPresses && diff < bestDiff)) {
                bestValue = value;
                bestPresses = presses;
                bestDiff = diff;
            }
        }
        System.out.println(bestValue);
    }
}
